  "implementation": "def solve(case):
    payload = case["payload"]
    edges = payload["edges"]
    refinement = payload["refinement"]
    if not isinstance(edges, list):
        raise ValueError("edges must be list")
    for e in edges:
        if not isinstance(e, list) or len(e) != 3:
            raise ValueError("each edge must be [u, v, w]")
        u, v, w = e
        if not isinstance(w, (int, float)):
            raise ValueError("weight must be numeric")
        if u not in refinement or v not in refinement:
            raise ValueError("edge endpoint not in refinement")
    if not isinstance(refinement, dict):
        raise ValueError("refinement must be dict")
    node_to_comm = dict(refinement)
    comm_to_nodes = {}
    for node, comm in node_to_comm.items():
        comm_to_nodes.setdefault(comm, []).append(node)
    for comm in comm_to_nodes:
        comm_to_nodes[comm].sort()
    aggregate = {}
    for u, v, w in edges:
        cu = node_to_comm[u]
        cv = node_to_comm[v]
        if cu <= cv:
            key = (cu, cv)
        else:
            key = (cv, cu)
        aggregate[key] = aggregate.get(key, 0) + w
    aggregate_edges = []
    for (c1, c2), total in aggregate.items():
        aggregate_edges.append([c1, c2, total])
    aggregate_edges.sort(key=lambda x: (x[0], x[1]))
    membership = []
    for comm in sorted(comm_to_nodes.keys()):
        membership.append([comm, comm_to_nodes[comm]])
    return {"aggregate_edges": aggregate_edges, "membership": membership}"
}
